"""
Test of the command bridge (src/control_loop.py, COMMAND_BRIDGE_CFG in src/task_config.py, design plan section 1, row M193), without a window and without cameras.

    python experiments/command_bridge_test.py

A scripted source gives arm targets on joint 3 of the left arm; each case loads the model afresh and runs a few simulated seconds:
  1. bridge OFF (the default): a 0.6 rad target step is applied at once (nothing changes without the bridge).
  2. bridge ON, a 0.2 rad step: accepted; the command moves toward it at most 0.01 rad per 50 Hz update (0.5 rad/s), reaches it, nothing is logged.
  3. bridge ON, a 0.6 rad step: rejected as a whole and logged with the joint, the value and the limit; the command does not move.
  4. bridge ON, a target outside the joint limits: rejected and logged; the command does not move.
  5. bridge ON, the tracking error limit set tiny (0.003 rad) while the command moves at 0.5 rad/s: commands are suspended (logged), the command stops, and they resume (logged) when the arm has caught up; the target is reached.
  6. bridge ON: a gripper command and a pedestal command are not limited (they are applied at once).
  7. bridge ON: the updates come at 50 Hz (the command changes only every 3rd tick).
Exit code 0 if every check passes.
"""

import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
os.environ.setdefault("MUJOCO_GL", "egl")

import numpy as np  # noqa: E402

from src.control_loop import run_loop  # noqa: E402
from experiments_loader import load, steps_per_frame, SPAWN  # noqa: E402

ROUTES = {k: "script" for k in ("base", "pedestal", "arms.left", "arms.right", "gripper.left", "gripper.right")}
RESULTS = []


def check(name, ok, detail=""):
    RESULTS.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}" + (f"   ({detail})" if detail else ""), flush=True)


def run(ticks, make_cmd, bridge=None):
    """Runs the loop for `ticks` ticks with a script make_cmd(tick, rest) -> command or None; returns (applied joint-3 target per tick, the loop's result, the model, the last obs)."""
    model, data = load()
    spf = steps_per_frame(model)
    seen = {"rest": None, "applied": [], "grip": [], "ped": []}

    def step(obs):
        if seen["rest"] is None:
            seen["rest"] = np.array(obs["applied"]["arm_targets"]["left"])
        seen["applied"].append(obs["applied"]["arm_targets"]["left"][2])
        seen["grip"].append(obs["applied"]["gripper"]["left"])
        seen["ped"].append(obs["applied"]["pedestal"])
        return make_cmd(obs["tick"], seen["rest"])

    cfg = {"source_hz": 1.0 / model.opt.timestep / spf, "spawn_pos": SPAWN, "cameras": False, "routes": ROUTES, "bench_frames": ticks}
    if bridge is not None:
        cfg["command_bridge"] = bridge
    res = run_loop(model, data, {"script": {"name": "script", "step": step}}, cfg, viewer=None)
    return np.array(seen["applied"]), res, seen


def arm_cmd(q3):
    return lambda k, rest: {"mode": "arms", "arm_targets": {"left": [float(x) for x in np.where(np.arange(7) == 2, q3, rest)]}} if k >= 30 else None


def main():
    print("1. bridge OFF: a 0.6 rad step is applied at once", flush=True)
    a, res, seen = run(120, lambda k, rest: {"mode": "arms", "arm_targets": {"left": [float(x) for x in (rest + np.where(np.arange(7) == 2, 0.6, 0.0))]}} if k >= 30 else None)
    check("the applied target jumped by 0.6 rad", abs(a[-1] - a[0] - 0.6) < 1e-6 and res["bridge_log"] == [], f"{a[0]:.3f} -> {a[-1]:.3f}")

    print("2. bridge ON: a 0.2 rad step is accepted and limited to 0.01 rad per update", flush=True)
    a, res, seen = run(240, lambda k, rest: {"mode": "arms", "arm_targets": {"left": [float(x) for x in (rest + np.where(np.arange(7) == 2, 0.2, 0.0))]}} if k >= 30 else None, {"enabled": True})
    steps = np.abs(np.diff(a))
    check("the command reached the target", abs(a[-1] - a[0] - 0.2) < 1e-6, f"{a[0]:.3f} -> {a[-1]:.3f}")
    check("no step above 0.01 rad per update", steps.max() <= 0.01 + 1e-9, f"largest {steps.max():.5f}")
    check("nothing logged", res["bridge_log"] == [], str(res["bridge_log"][:2]))
    upd = np.nonzero(steps > 1e-12)[0]
    check("updates come only every 3rd tick (50 Hz)", len(upd) > 5 and len(set(np.diff(upd))) == 1 and int(np.diff(upd)[0]) == 3, f"gaps {sorted(set(np.diff(upd).tolist()))}")

    print("3. bridge ON: a 0.6 rad step is rejected as a whole and logged", flush=True)
    a, res, seen = run(150, lambda k, rest: {"mode": "arms", "arm_targets": {"left": [float(x) for x in (rest + np.where(np.arange(7) == 2, 0.6, 0.0))]}} if k >= 30 else None, {"enabled": True})
    ev = [e for e in res["bridge_log"] if "step too large" in e["kind"]]
    check("the command did not move", abs(a[-1] - a[0]) < 1e-9, f"{a[0]:.3f} -> {a[-1]:.3f}")
    check("rejections logged with joint, value and limit", len(ev) > 0 and ev[0]["side"] == "left" and ev[0]["joint"] == 3 and abs(ev[0]["value"] - 0.6) < 1e-6 and ev[0]["limit"] == 0.25 and ev[0]["count"] > 10, str(ev[:1]))

    print("4. bridge ON: a target outside the joint limits is rejected and logged", flush=True)
    a, res, seen = run(150, lambda k, rest: {"mode": "arms", "arm_targets": {"left": [float(x) for x in np.where(np.arange(7) == 2, 10.0, rest)]}} if k >= 30 else None, {"enabled": True})
    ev = [e for e in res["bridge_log"] if "joint limits" in e["kind"]]
    check("the command did not move", abs(a[-1] - a[0]) < 1e-9, f"{a[0]:.3f} -> {a[-1]:.3f}")
    check("logged with joint 3, value 10 and the limit", len(ev) > 0 and ev[0]["joint"] == 3 and ev[0]["value"] == 10.0 and abs(ev[0]["limit"]) < 10, str(ev[:1]))

    print("5. bridge ON, tracking error limit 0.003 rad: suspension and resumption are logged, the target is still reached", flush=True)
    a, res, seen = run(420, lambda k, rest: {"mode": "arms", "arm_targets": {"left": [float(x) for x in (rest + np.where(np.arange(7) == 2, 0.2, 0.0))]}} if k >= 30 else None,
                       {"enabled": True, "max_tracking_error_rad": 0.003})
    sus = [e for e in res["bridge_log"] if e["kind"].startswith("suspended")]
    resu = [e for e in res["bridge_log"] if e["kind"].startswith("resumed")]
    check("a suspension was logged with the joint, the error and the limit", len(sus) > 0 and sus[0]["limit"] == 0.003 and sus[0]["value"] > 0.003, str(sus[:1]))
    check("the resumption was logged", len(resu) > 0)
    check("the target was reached", abs(a[-1] - a[0] - 0.2) < 1e-3, f"{a[0]:.3f} -> {a[-1]:.3f}")

    print("6. bridge ON: the gripper and the pedestal are not limited", flush=True)
    a, res, seen = run(150, lambda k, rest: {"mode": "arms", "gripper": {"left": 0.0}} if k >= 30 else None, {"enabled": True})
    g = np.array(seen["grip"])
    check("the gripper target was applied at once", abs(g[-1] - 0.0) < 1e-9 and abs(g[0] - g[-1]) > 1e-4, f"{g[0]:.4f} -> {g[-1]:.4f}")
    p0 = None
    a, res, seen = run(150, lambda k, rest: {"mode": "pedestal", "height": 0.12} if k >= 30 else None, {"enabled": True})
    p = np.array(seen["ped"])
    check("the pedestal target was applied at once", abs(p[-1] - 0.12) < 1e-9, f"{p[0]:.3f} -> {p[-1]:.3f}")
    ok = all(RESULTS)
    print(f"\n{sum(RESULTS)}/{len(RESULTS)} checks passed", flush=True)
    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main())
